// Port of internal/portable, for the direct-Canvas mode: the plugin builds
// paths from a Canvas listing itself, and they must be the paths the worker
// would have written. schema/canvas-paths.json (generated by the worker) pins
// that, via canvas.test.ts.
//
// Lengths are UTF-8 BYTES, as in Go, never UTF-16 code units: "講義" is six
// bytes to the worker and two units to JavaScript.
//
// Pure.

export const MAX_COMPONENT = 120;
export const MAX_TOTAL = 400;
const MAX_EXT = 16;

const RESERVED = new Set([
  "CON", "PRN", "AUX", "NUL",
  "COM1", "COM2", "COM3", "COM4", "COM5", "COM6", "COM7", "COM8", "COM9",
  "LPT1", "LPT2", "LPT3", "LPT4", "LPT5", "LPT6", "LPT7", "LPT8", "LPT9",
]);

const enc = new TextEncoder();
const dec = new TextDecoder();
const bytes = (s: string) => enc.encode(s).length;

/** Go's unicode.IsControl: C0, DEL and C1. */
function isControl(ch: string): boolean {
  const c = ch.codePointAt(0)!;
  return c <= 0x1f || (c >= 0x7f && c <= 0x9f);
}

/** Sanitise one path segment. Throws when nothing portable is left. */
export function component(s: string): string {
  let out = [...s.normalize("NFC")]
    .filter((ch) => !isControl(ch))
    .join("")
    .replace(/[/\\<>:"|?*]/g, "-");
  // Windows silently strips trailing dots and spaces.
  out = out.replace(/[. ]+$/, "").replace(/^ +/, "");
  if (out === "" || out === "." || out === "..") {
    throw new Error(`portable: component ${JSON.stringify(s)} is empty after sanitisation`);
  }
  if (RESERVED.has(stem(out).toUpperCase())) out = `_${out}`;
  if (bytes(out) > MAX_COMPONENT) {
    out = truncateKeepExt(out, MAX_COMPONENT);
    if (out === "") throw new Error(`portable: component ${JSON.stringify(s)} empty after truncation`);
  }
  return out;
}

/** Sanitise every segment of a slash-separated path; refuse escapes. */
export function path(p: string): string {
  p = p.replace(/\\/g, "/");
  if (p.startsWith("/")) throw new Error(`portable: absolute path ${JSON.stringify(p)}`);
  const out: string[] = [];
  for (const part of p.split("/")) {
    if (part === "" || part === ".") continue;
    if (part === "..") throw new Error(`portable: traversal in ${JSON.stringify(p)}`);
    out.push(component(part));
  }
  if (out.length === 0) throw new Error(`portable: path ${JSON.stringify(p)} is empty`);
  const joined = out.join("/");
  if (bytes(joined) > MAX_TOTAL) {
    throw new Error(`portable: path ${JSON.stringify(joined)} exceeds ${MAX_TOTAL} bytes`);
  }
  return joined;
}

/** "a/b.pdf" + 7 -> "a/b (7).pdf", shortening the stem to stay under MAX_COMPONENT. */
export function disambiguate(p: string, canvasId: number): string {
  const slash = p.lastIndexOf("/");
  const dir = slash >= 0 ? p.slice(0, slash + 1) : "";
  const name = slash >= 0 ? p.slice(slash + 1) : p;
  const suffix = ` (${canvasId})`;
  let stemPart = name;
  let ext = "";
  const dot = name.lastIndexOf(".");
  if (dot > 0) {
    stemPart = name.slice(0, dot);
    ext = name.slice(dot);
  }
  const over = bytes(stemPart) + bytes(suffix) + bytes(ext) - MAX_COMPONENT;
  if (over > 0) {
    stemPart = truncateBytes(stemPart, Math.max(0, bytes(stemPart) - over)).replace(/[. ]+$/, "");
  }
  return dir + stemPart + suffix + ext;
}

/** Two paths with one key are one file on Windows and default macOS. */
export function collisionKey(p: string): string {
  return p.normalize("NFC").toLowerCase();
}

/** Stand-in name for a Canvas file whose real name cannot be made portable. */
export function fallback(original: string, canvasId: number): string {
  const name = `canvas-file-${canvasId}`;
  const dot = original.lastIndexOf(".");
  if (dot > 0 && bytes(original) - bytes(original.slice(0, dot)) - 1 <= MAX_EXT) {
    try {
      const ext = component(original.slice(dot + 1));
      if (!/[ .]/.test(ext)) return `${name}.${ext}`;
    } catch {
      // No usable extension; the bare stand-in will do.
    }
  }
  return name;
}

function stem(s: string): string {
  const i = s.indexOf(".");
  return i > 0 ? s.slice(0, i) : s;
}

function truncateKeepExt(s: string, n: number): string {
  let stemPart = s;
  let ext = "";
  const dot = s.lastIndexOf(".");
  if (dot > 0 && bytes(s) - bytes(s.slice(0, dot)) - 1 <= MAX_EXT) {
    stemPart = s.slice(0, dot);
    ext = s.slice(dot);
  }
  if (bytes(ext) >= n) return truncateBytes(s, n).replace(/[. ]+$/, "");
  stemPart = truncateBytes(stemPart, n - bytes(ext)).replace(/[. ]+$/, "");
  if (stemPart === "") return "";
  return stemPart + ext;
}

/** Cut to at most n UTF-8 bytes without splitting a character. */
function truncateBytes(s: string, n: number): string {
  const b = enc.encode(s);
  if (b.length <= n) return s;
  // Back off continuation bytes (10xxxxxx) to the start of a character.
  while (n > 0 && (b[n]! & 0xc0) === 0x80) n--;
  return dec.decode(b.subarray(0, n));
}
